def approve_recorded_minutes(apps, schema_editor):
    """Minutes recorded before approval existed were already read by the invitees: keep them readable."""
    Meeting = apps.get_model("regions", "Meeting")
    for meeting in Meeting.objects.exclude(minutes="").filter(minutes_status=""):
        meeting.minutes_status = "approved"
        meeting.minutes_approved_at = meeting.minutes_recorded_at
        meeting.save(update_fields=["minutes_status", "minutes_approved_at"])


